(()=>{const e=document.getElementById("search-input"),n=document.getElementById("search-results"),t=document.getElementById("search-status");let s=[];e.disabled=!0,fetch("/index.json").then(e=>{if(!e.ok)throw Error();return e.json()}).then(t=>{s=t,e.disabled=!1,e.focus()}).catch(()=>{t.textContent="Search could not load. Please try again or browse the writing page."}),e.addEventListener("input",()=>{n.replaceChildren();const i=e.value.trim().toLowerCase();if(!i){t.textContent="";return}const o=s.filter(e=>(e.title+" "+e.content).toLowerCase().includes(i));t.textContent=o.length+" matching "+(o.length===1?"note":"notes");for(const e of o){const t=document.createElement("article"),i=document.createElement("h2"),s=document.createElement("a"),a=document.createElement("p");t.className="search-result",s.href=e.permalink,s.textContent=e.title,a.textContent=e.summary.slice(0,230),i.append(s),t.append(i,a),n.append(t)}})})()